style.css:
@-moz-document domain("chatgpt.com") {
/* WARM CREAM BACKGROUND */
html, body {
  background-color: #F7F1E7 !important;
}

/* MAIN CHAT AREA */
main {
  background-color: #F7F1E7 !important;
  color: #40291F !important;
}

/* GEORGIA TYPOGRAPHY */
main p,
main li,
main h1,
main h2,
main h3,
main blockquote,
main [contenteditable="true"],
main textarea {
  font-family: Georgia, "Times New Roman", serif !important;
  color: #40291F !important;
  line-height: 1.75 !important;
}

/* USER MESSAGE BUBBLES */
[data-message-author-role="user"] {
  background-color: #E9DDCB !important;
  border-radius: 18px !important;
}

/* COMPOSER */
form {
  background-color: #E9DDCB !important;
  border: 1px solid #C5A98A !important;
  border-radius: 20px !important;
}

/* BUTTONS AND ACCENTS */
button {
  color: #79543D !important;
}

/* LINKS */
main a {
  color: #79543D !important;
}

/* SIDEBAR */
nav,
aside {
  background-color: #EFE5D7 !important;
}

/* SUBTLE BORDERS */
hr {
  border-color: #C5A98A !important;
}
}
